import buildings from './buildings.json'
export * from './services'

/**
 * The campus map's building list: ETH's buildings (shipped, `buildings.json`, regenerated by
 * `tooling/buildings.mjs`), their search and their campus groups. The service parsers are in `services.ts`.
 */
export type CampusGroup = 'zentrum' | 'hoengg' | 'other'
export const CAMPUS_GROUPS: CampusGroup[] = ['zentrum', 'hoengg', 'other']

export interface Building {
  code: string
  street: string
  zip: string
  city: string
  canton: string
  link: string
  campus: CampusGroup
  /** Centre of the outline, [longitude, latitude]. */
  center: [number, number]
}

export const BUILDINGS: Building[] = buildings as Building[]
const BY_CODE = new Map(BUILDINGS.map(building => [building.code, building]))
export const buildingOf = (code: unknown): Building | null => typeof code === 'string' ? BY_CODE.get(code) ?? null : null

export const addressOf = (building: Building) => [building.street, [building.zip, building.city].filter(Boolean).join(' ')].filter(Boolean).join(', ')

/** Lower case without diacritics; "ue" also matches "ü" typed as "u" (Hönggerberg, Zürich). */
export function fold(text: string): string {
  return text.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/([aou])e/g, '$1')
}

/**
 * The buildings matching `text`: every word must occur in the code or the address. A code that
 * starts with the query comes first, then other code matches, then address matches; ties by code.
 */
export function searchBuildings(text: string, list: Building[] = BUILDINGS): Building[] {
  const words = fold(text).split(/[\s,]+/).filter(Boolean)
  if (!words.length) return list
  const scored: { building: Building; score: number }[] = []
  for (const building of list) {
    const code = fold(building.code)
    const haystack = `${code} ${fold(addressOf(building))} ${fold(building.canton)}`
    if (!words.every(word => haystack.includes(word))) continue
    const first = words[0]
    scored.push({ building, score: code === first ? 0 : code.startsWith(first) ? 1 : code.includes(first) ? 2 : 3 })
  }
  return scored.sort((a, b) => a.score - b.score || a.building.code.localeCompare(b.building.code)).map(item => item.building)
}

export function groupBuildings(list: Building[]): { group: CampusGroup; buildings: Building[] }[] {
  return CAMPUS_GROUPS.map(group => ({ group, buildings: list.filter(building => building.campus === group) })).filter(entry => entry.buildings.length)
}

